#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char buf[4096];
    int count = 0;
    if (fgets(buf, sizeof(buf), stdin) != NULL) {
        size_t n = strlen(buf);
        for (size_t i = 0; i < n; i++) {
            char c = (char)tolower((unsigned char)buf[i]);
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                count++;
            }
        }
    }
    printf("%d\n", count);
    return 0;
}
