    int max_val;
    if (scanf("%d", &max_val) != 1) return 0;

    for (int i = 1; i < n; i++) {
        int val;
        scanf("%d", &val);
        if (val > max_val) {
            max_val = val;
        }
    }

    printf("%d\n", max_val);
    return 0;
}
